// CrowdRelay decided WHO gets asked, about WHICH show, and HOW MANY
// codes are on offer. This workflow delivers one ask to one verified scene
// partner by the channel the workspace uses for them. It never issues
// invite codes (CrowdRelay does, when the partner answers yes), never
// broadens the recipient, and never re-asks on its own schedule.
const e = $json;
if (!e || e.type !== 'crowdrelay.beacon.invite_batch_requested' || e.version !== 1) return [];
const d = e.data ?? {};
for (const key of ['action_id', 'beacon_id', 'beacon_version', 'event_id', 'requested_count', 'beacon_name', 'contact_email']) {
  if (!d[key]) throw new Error('invite batch request missing ' + key);
}
if (!d.contact_email.includes('@')) throw new Error('invalid contact_email');
if (!Number.isInteger(d.requested_count) || d.requested_count < 1 || d.requested_count > 100) {
  throw new Error('requested_count out of bounds');
}
return [{ json: {
  action_id: String(d.action_id),
  beacon_name: String(d.beacon_name),
  contact_email: String(d.contact_email),
  requested_count: d.requested_count,
  event_title: String(d.event?.title || ''),
  event_slug: String(d.event?.slug || ''),
  starts_at: String(d.event?.starts_at || ''),
}}];

// Fail closed. Only `claimed` may contact the partner; `already_succeeded`
// is a no-op replay; `in_flight` and `ambiguous` require reconciliation
// instead of a second ask.
const c = $input.first().json;
const plan = $('Validate invite batch request').first().json;
if (c.status === 'already_succeeded') return [];
if (c.status !== 'claimed') throw new Error('claim not granted: ' + c.status);
return [{ json: { ...plan, claim_token: c.claim_token } }];

// One concrete ask, one show, one number of codes. Identifies who is
// asking, states where the address came from (their verified listing), and
// carries an explicit opt-out. No fake urgency, no reciprocal-for-placement
// language, nothing about money.
const p = $input.first().json;
const subject = 'VIRYA w ' + p.event_title + ' - zestaw zaproszen dla Twojej spolecznosci';
const text = [
  'Czesc ' + p.beacon_name + ',',
  '',
  'Jestes zweryfikowanym partnerem scene na ' + p.event_title + ' i dlatego pisze najpierw do Ciebie.',
  'Mozemy przygotowac dla Ciebie zestaw ' + p.requested_count + ' unikalnych kodow zaproszen dla osob, ktore chcesz przyciagnac na koncert.',
  'Kody sa jednorazowe i pilnowane przez nasz system - kazde zgloszenie przez kod jest przypisane do Ciebie jako partnera.',
  '',
  'Odpowiedz krotko "tak" na tego maila, a zestaw przeslemy od razu.',
  '',
  '- Virya / CrowdRelay',
  'Adres wzity z Waszej publicznie dostepnej, zweryfikowanej listy partnerow sceny.',
  'Jesli nie chcesz otrzymywac takich prosb, odpowiedz "rezygnuje".'
].join('\n');
return [{ json: { ...p, subject, text } }];
